<div class="d-flex justify-content-between gap-3 align-items-center mb-3"><div><h1 class="h3">Usuarios y accesos</h1><p class="text-muted mb-0">Administra cuentas, roles, activación y contraseñas.</p></div><a class="btn btn-primary" href="<?= BASE_URL ?>/users/create">Nuevo usuario</a></div>
<?php if ($success): ?><div class="alert alert-success" role="status"><?= e($success) ?></div><?php endif; ?>
<form class="d-flex gap-2 mb-4" method="get" action="<?= BASE_URL ?>/users"><label class="visually-hidden" for="q">Nombre o correo</label><input class="form-control" id="q" name="q" maxlength="160" value="<?= e($query) ?>" placeholder="Buscar por nombre, apellido o correo"><button class="btn btn-outline-primary">Buscar</button><a class="btn btn-outline-secondary" href="<?= BASE_URL ?>/users">Limpiar</a></form>
<?php if (!$accounts): ?><div class="card card-body text-center py-5">No hay usuarios para esta búsqueda.</div><?php else: ?><div class="card table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Usuario</th><th>Rol</th><th>Estado</th><th>Último acceso</th><th>Acciones</th></tr></thead><tbody><?php foreach ($accounts as $item): ?><tr><td><strong><?= e($item['nombres'].' '.$item['apellidos']) ?></strong><div class="small text-muted"><?= e($item['email']) ?></div><?php if ($item['password_change_required']): ?><span class="badge text-bg-warning">Debe cambiar contraseña</span><?php endif; ?></td><td><?= e($item['rol']) ?></td><td><span class="badge <?= $item['estado'] ? 'text-bg-success' : 'text-bg-secondary' ?>"><?= $item['estado'] ? 'Activo' : 'Inactivo' ?></span></td><td><?= e($item['ultimo_acceso'] ?? 'Aún no ha ingresado') ?></td><td><a class="btn btn-sm btn-outline-primary" href="<?= BASE_URL ?>/users/edit?id=<?= (int)$item['id'] ?>">Gestionar</a></td></tr><?php endforeach; ?></tbody></table></div><p class="small text-muted mt-2">Hasta 100 usuarios. Las cuentas inactivas conservan sus consultas, visitas y operaciones históricas.</p><?php endif; ?>
